def load_tools(mcp: FastMCP, db) -> None:
    rows = db.execute("SELECT name, description, input_schema, handler FROM tool_defs").fetchall()
    for row in rows:
        mcp.add_tool(
            HANDLERS[row.handler],
            name=row.name,
            description=row.description,
        )
        SCHEMAS[row.name] = json.loads(row.input_schema)

