LOG_DIR = Path("/var/log/acme").resolve()
LOG_NAME = re.compile(r"[a-z0-9_-]{1,64}\.log")

@mcp.tool()
def read_log(name: str) -> str:
    """Read one application log file by name."""
    if not LOG_NAME.fullmatch(name):
        raise ValueError("invalid log name")
    path = (LOG_DIR / name).resolve()
    if path.parent != LOG_DIR:
        raise ValueError("invalid log name")
    return path.read_text()[-20000:]

