class Confirm(BaseModel):
    confirm: bool

@mcp.tool()
async def delete_document(doc_id: int, ctx: Context) -> str:
    """Permanently delete a document from the workspace."""
    doc = docs.get(doc_id)
    if doc is None or not acl.can_delete(current_user(ctx), doc):
        raise PermissionError("not allowed")
    answer = await ctx.elicit(f"Delete '{doc.title}' permanently?", schema=Confirm)
    if answer.action != "accept" or not answer.data.confirm:
        return "cancelled"
    docs.hard_delete(doc.id)
    return "deleted"

